CREATE TABLE IF NOT EXISTS workspaces (id TEXT PRIMARY KEY, revision INTEGER NOT NULL DEFAULT 1, document TEXT NOT NULL, created TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions (digest TEXT PRIMARY KEY, workspace TEXT NOT NULL REFERENCES workspaces(id), store_id TEXT, expires TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS sessions_workspace ON sessions(workspace);
CREATE TABLE IF NOT EXISTS counters (label TEXT PRIMARY KEY, n INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS files (id TEXT PRIMARY KEY, workspace TEXT NOT NULL REFERENCES workspaces(id), support_id TEXT NOT NULL, revision INTEGER NOT NULL, name TEXT NOT NULL, mime TEXT NOT NULL, content TEXT NOT NULL);
